#!/usr/bin/perl
# Cleans a collaboration graph generated by Doxygen (.dot file) for a class that uses class templates:
#   1. Doxygen draws a class template twice, once as the template (e.g. "Data::DT_Data< T >") and once as the
#      instance (e.g. "Data::DT_Data< double >"), linked by an orange edge. Each instance is merged into its
#      template.
#   2. For C++, Doxygen may also draw the same template several times (e.g. two "Models::DT_Model< T >"
#      nodes). Nodes with the same class title are merged into the first one.
# so that every class appears once; the edges that become identical are kept once.
#
# Usage:  perl merge_template_nodes.pl input.dot > output.dot
use strict;
use warnings;

local $/;                                   # read the whole file
my $dot = <>;
my ($head, $body) = $dot =~ /^(.*?\n)(  Node\d+ .*)$/s or die "Not a Doxygen graph\n";
my @statements = split /(?<=\];)\n/, $body; # every statement ends with "];"

# 1. orange edges: template -> instance
my %merged_into;
for (@statements) {
    $merged_into{$2} = $1 if /^\s*(Node\d+) -> (Node\d+) \[[^\n]*color="orange"/;
}

# 2. nodes with the same title: merged into the first one
my %first_with_title;
for (@statements) {
    next unless /^\s*(Node\d+) \[/;
    my $id = $1;
    my ($title) = /COLSPAN="2"[^>]*>(.*?)<\/TD><\/TR>/s or next;
    $title =~ s/<[^>]*>//g;
    $title =~ s/\s+//g;
    if (exists $first_with_title{$title}) {
        $merged_into{$id} //= $first_with_title{$title};
    } else {
        $first_with_title{$title} = $id;
    }
}

# follow chains (instance -> template -> first template with that title)
sub target {
    my $id = shift;
    my %seen;
    while (exists $merged_into{$id} && !$seen{$id}++) { $id = $merged_into{$id}; }
    return $id;
}

# 3. drop the orange edges and the merged nodes, redirect the other edges, keep each edge once
my (@kept, %edge_seen);
for (@statements) {
    next if /^\s*Node\d+ -> Node\d+ \[[^\n]*color="orange"/;
    next if /^\s*(Node\d+) \[/ && exists $merged_into{$1};
    s/\b(Node\d+)\b(?= ->| \[id="edge)/target($1)/ge;
    if (/^\s*(Node\d+) -> (Node\d+) \[/) {
        my ($from, $to) = ($1, $2);
        next if $from eq $to;
        my ($label) = /label="([^"]*)"/;
        my ($color) = /color="([^"]*)"/;
        my ($tail) = /arrowtail="([^"]*)"/;
        next if $edge_seen{join '|', $from, $to, $label // '', $color // '', $tail // ''}++;
    }
    push @kept, $_;
}
print $head, join("\n", @kept);
